# JavaScript problem - Python equivalent:
def invert_object(obj):
    res = {}
    for k, v in obj.items():
        v_str = str(v)
        if v_str in res:
            if isinstance(res[v_str], list):
                res[v_str].append(k)
            else:
                res[v_str] = [res[v_str], k]
        else:
            res[v_str] = k
    return res

# JavaScript problem - Python equivalent:
def deep_filter(obj, fn):
    if isinstance(obj, dict):
        res = {}
        for k, v in obj.items():
            filtered = deep_filter(v, fn)
            if filtered is not None:
                res[k] = filtered
        return res if res else None
    elif isinstance(obj, list):
        res = [deep_filter(x, fn) for x in obj]
        res = [x for x in res if x is not None]
        return res if res else None
    else:
        return obj if fn(obj) else None

def countPairs(self, nums, target):
    nums.sort()
    left, right = 0, len(nums) - 1
    count = 0
    while left < right:
        if nums[left] + nums[right] < target:
            count += right - left
            left += 1
        else:
            right -= 1
    return count

