def maximizeTheProfit(self, n, offers):
    from collections import defaultdict
    end_map = defaultdict(list)
    for s, e, gold in offers:
        end_map[e].append((s, gold))
    dp = [0] * (n + 1)
    for i in range(n):
        dp[i + 1] = dp[i]
