def minOperationsQueries(self, n, edges, queries):
    from collections import defaultdict
    LOG = n.bit_length()
    adj = defaultdict(list)
    for u, v, w in edges:
        adj[u].append((v, w))
        adj[v].append((u, w))
    depth = [0] * n
    parent = [[0]*n for _ in range(LOG)]
    freq = [[[0]*27 for _ in range(n)] for _ in range(LOG)]
    # BFS to set up
    from collections import deque
    visited = [False] * n
    visited[0] = True
    queue = deque([0])
    while queue:
        u = queue.popleft()
        for v, w in adj[u]:
            if not visited[v]:
                visited[v] = True
                depth[v] = depth[u] + 1
                parent[0][v] = u
                freq[0][v][w] = 1
                queue.append(v)
    for j in range(1, LOG):
        for i in range(n):
            parent[j][i] = parent[j-1][parent[j-1][i]]
            for w in range(1, 27):
                freq[j][i][w] = freq[j-1][i][w] + freq[j-1][parent[j-1][i]][w]
    def lca_query(u, v):
        if depth[u] < depth[v]: u, v = v, u
        diff = depth[u] - depth[v]
        cnt = [0] * 27
        for j in range(LOG):
            if diff >> j & 1:
                for w in range(1, 27):
                    cnt[w] += freq[j][u][w]
                u = parent[j][u]
        if u == v:
            path_len = sum(cnt[1:])
            return path_len - max(cnt[1:]) if path_len > 0 else 0
        for j in range(LOG-1, -1, -1):
            if parent[j][u] != parent[j][v]:
                for w in range(1, 27):
                    cnt[w] += freq[j][u][w] + freq[j][v][w]
                u = parent[j][u]
                v = parent[j][v]
        for w in range(1, 27):
            cnt[w] += freq[0][u][w] + freq[0][v][w]
        path_len = sum(cnt[1:])
        return path_len - max(cnt[1:]) if path_len > 0 else 0
    return [lca_query(u, v) for u, v in queries]

def smallestNumber(self, n):
