def numberOfWays(self, s, t, k):
    MOD = 10**9 + 7
    n = len(s)
    # Find number of valid rotations using KMP on t + s + s
    def kmp_count(text, pattern):
        lps = [0] * len(pattern)
        j = 0
        for i in range(1, len(pattern)):
            while j and pattern[i] != pattern[j]:
                j = lps[j-1]
            if pattern[i] == pattern[j]:
                j += 1
            lps[i] = j
        count = 0
        j = 0
        for i in range(len(text)):
            while j and text[i] != pattern[j]:
                j = lps[j-1]
            if text[i] == pattern[j]:
                j += 1
            if j == len(pattern):
                count += 1
                j = lps[j-1]
        return count
    m = kmp_count((s + s)[1:], t)  # rotations that match (excluding 0)
    has_zero = 1 if s == t else 0
    m_match = m + has_zero  # total rotations matching (0..n-1)
    # Matrix exponent: states = {match, no_match}
    # transition: from match, choose one of m_match-1 matches or n-m_match non-matches
    # Actually use formula: f(k) for number of ways
    def mat_mul(A, B):
        return [[(A[0][0]*B[0][0] + A[0][1]*B[1][0]) % MOD, (A[0][0]*B[0][1] + A[0][1]*B[1][1]) % MOD],
                [(A[1][0]*B[0][0] + A[1][1]*B[1][0]) % MOD, (A[1][0]*B[0][1] + A[1][1]*B[1][1]) % MOD]]
    def mat_pow(M, p):
        result = [[1,0],[0,1]]
        while p:
            if p & 1:
                result = mat_mul(result, M)
            M = mat_mul(M, M)
            p >>= 1
        return result
    # Transition matrix: from state match/non-match
    # match -> match: m_match - 1 choices, match -> non: n - m_match
    # non -> match: m_match choices, non -> non: n - m_match - 1
    M = [[m_match - 1, n - m_match], [m_match, n - m_match - 1]]
    res = mat_pow(M, k)
    # initial state: s == t -> start in match state
    if s == t:
        return res[0][0] % MOD
    else:
        return res[1][0] % MOD

def sumRemoteness(self, grid):
    n, m = len(grid), len(grid[0])
    total = 0
    cells = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] != -1:
                total += grid[i][j]
                cells += 1
    visited = [[False]*m for _ in range(n)]
    ans = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] != -1 and not visited[i][j]:
                # BFS to find component
                comp_sum = 0
                comp_size = 0
                stack = [(i, j)]
                visited[i][j] = True
                while stack:
                    x, y = stack.pop()
                    comp_sum += grid[x][y]
                    comp_size += 1
                    for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                        nx, ny = x+dx, y+dy
                        if 0<=nx<n and 0<=ny<m and not visited[nx][ny] and grid[nx][ny]!=-1:
                            visited[nx][ny] = True
                            stack.append((nx, ny))
                # each cell in this component contributes (total - comp_sum) to remoteness
                ans += comp_size * (total - comp_sum)
    return ans

