def minEdgeReversals(self, n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append((v, 0))  # forward edge, no reversal needed
        adj[v].append((u, 1))  # backward edge, reversal needed
    # DFS from 0 to count reversals
    ans = [0] * n
    def dfs(u, parent):
        for v, cost in adj[u]:
            if v != parent:
                ans[0] += cost
                dfs(v, u)
    dfs(0, -1)
    # Reroot
    def reroot(u, parent):
        for v, cost in adj[u]:
            if v != parent:
                # edge u->v: cost=0 means forward, moving root to v means we now need to reverse it: +1
                # edge v->u: cost=1 means we reversed it for root=0, now it's free: -1
                ans[v] = ans[u] + (1 if cost == 0 else -1)
                reroot(v, u)
    reroot(0, -1)
    return ans

