def maximumSum(self, nums):
    from collections import defaultdict
    n = len(nums)
    def square_free(x):
        res = 1
        d = 2
        while d * d <= x:
            cnt = 0
            while x % d == 0:
                x //= d
                cnt += 1
            if cnt % 2 == 1:
                res *= d
            d += 1
        if x > 1:
            res *= x
        return res
    groups = defaultdict(int)
    for i in range(1, n + 1):
        groups[square_free(i)] += nums[i - 1]
    return max(groups.values())

def maximumSumOfHeights(self, maxHeights):
