    # left[i] = max sum of mountain left side ending at i
    left = [0] * n
    stack = []
    for i in range(n):
        while stack and maxHeights[stack[-1]] >= maxHeights[i]:
            stack.pop()
        if not stack:
            left[i] = maxHeights[i] * (i + 1)
        else:
            left[i] = left[stack[-1]] + maxHeights[i] * (i - stack[-1])
        stack.append(i)
    right = [0] * n
