            x = parent[x]
        return x
    def union(x, y):
        px, py = find(x), find(y)
        if px == py: return
        if size[px] < size[py]: px, py = py, px
        parent[py] = px
        size[px] += size[py]
    for u, v in edges:
        if not is_prime[u] and not is_prime[v]:
            union(u, v)
    ans = 0
    for u in range(1, n + 1):
        if not is_prime[u]:
            continue
        # u is prime, look at adjacent non-prime components
        components = []
        for v in adj[u]:
            if not is_prime[v]:
                components.append(size[find(v)])
        # paths through u with exactly one prime (u itself)
        total = 0
        for sz in components:
            ans += sz + total * sz
            total += sz
        ans += 1  # path of just u? No, path needs length >= 1
        # actually single edges from u to non-prime are counted in sz
    # But we also count paths that are just u to a non-prime neighbor
    # The formula: for each prime u, paths = sum(sz_i) + sum(sz_i * sz_j for i<j)
    # Let me fix
    ans = 0
    for u in range(1, n + 1):
        if not is_prime[u]: continue
        components = []
        for v in adj[u]:
            if not is_prime[v]:
                components.append(size[find(v)])
        s = sum(components)
        ans += s  # paths: non-prime -> prime u
        # paths through u between two different components
        for sz in components:
            ans += sz * (s - sz) // 1
        # but double counted pairs
    # Fix: use prefix sum approach
    ans = 0
    for u in range(1, n + 1):
        if not is_prime[u]: continue
        prev = 0
        for v in adj[u]:
            if not is_prime[v]:
                sz = size[find(v)]
                ans += sz * (prev + 1)
                prev += sz
    return ans

def canAliceWin(self, a, b):
    # Alice plays from a, Bob from b
    # Each player must play word > last word (by first char comparison)
    i, j = 0, 0
    last = ''
    alice_turn = True
    while True:
        if alice_turn:
            # find next playable word in a
            while i < len(a) and a[i] <= last:
                i += 1
            if i >= len(a):
                return False
            last = a[i]
            i += 1
        else:
            while j < len(b) and b[j] <= last:
                j += 1
            if j >= len(b):
                return True
            last = b[j]
            j += 1
        alice_turn = not alice_turn

def minOperations(self, nums, k):
    seen = set()
    for i in range(len(nums) - 1, -1, -1):
        if nums[i] <= k:
            seen.add(nums[i])
        if len(seen) == k:
            return len(nums) - i
    return len(nums)

def minOperations(self, nums):
    from collections import Counter
    freq = Counter(nums)
    ops = 0
    for f in freq.values():
        if f == 1:
            return -1
        ops += (f + 2) // 3
    return ops

def maxSubarrays(self, nums):
    total_and = nums[0]
    for x in nums:
        total_and &= x
    if total_and != 0:
        return 1
    count = 0
    running = -1  # all bits set
    for x in nums:
        running &= x
        if running == 0:
            count += 1
            running = -1
    return max(count, 1)

def maxKDivisibleComponents(self, n, edges, values, k):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    ans = 0
    def dfs(u, parent):
        nonlocal ans
        total = values[u]
        for v in adj[u]:
            if v != parent:
                total += dfs(v, u)
        if total % k == 0:
            ans += 1
            return 0
        return total
    dfs(0, -1)
    return ans

def countVisitedNodes(self, edges):
    n = len(edges)
    ans = [0] * n
    visited = [0] * n  # 0=unvisited, 1=in progress, 2=done
    def process(start):
        path = []
        node = start
        while visited[node] == 0:
            visited[node] = 1
            path.append(node)
            node = edges[node]
        if visited[node] == 1:
            # found cycle
            cycle_start = path.index(node)
            cycle_len = len(path) - cycle_start
            for i in range(cycle_start, len(path)):
                ans[path[i]] = cycle_len
                visited[path[i]] = 2
            for i in range(cycle_start - 1, -1, -1):
                ans[path[i]] = ans[path[i+1]] + 1
                visited[path[i]] = 2
        else:
            # node already processed
            for i in range(len(path) - 1, -1, -1):
                ans[path[i]] = ans[node] + (len(path) - i)
                visited[path[i]] = 2
    for i in range(n):
        if visited[i] == 0:
            process(i)
    return ans

